import pandas as pd
import json
import numpy as np

# Read the data file
df = pd.read_csv("/home/chs/Work/tga_plot/eval/inputs_b/isothermal.txt", sep=None, engine='python')

# Identify columns based on preview: Time (min), Temperature (°C), Weight (%)
time_col = "Time (min)"
temp_col = "Temperature (°C)"
weight_col = "Weight (%)"

# Prepare data for ECharts
time_data = df[time_col].tolist()
temp_data = df[temp_col].tolist()
weight_data = df[weight_col].tolist()

# Find weight at 140 min for residue label using numpy argmin on absolute difference
diffs = np.abs(df[time_col] - 140.0)
idx_140 = diffs.idxmin()
weight_at_140 = df.loc[idx_140, weight_col]
time_at_140 = df.loc[idx_140, time_col]

# Construct the ECharts option
option = {
    "title": {
        "text": "isothermal",
        "left": "center"
    },
    "tooltip": {
        "trigger": "axis"
    },
    "legend": {
        "data": ["Weight (%)", "Temperature (°C)"],
        "top": "5%"
    },
    "grid": {
        "left": "3%",
        "right": "4%",
        "bottom": "3%",
        "containLabel": True
    },
    "xAxis": {
        "type": "value",
        "name": "시간 (분)",
        "nameLocation": "middle",
        "nameGap": 25,
        "axisLabel": {
            "fontFamily": "Noto Sans CJK KR"
        }
    },
    "yAxis": [
        {
            "type": "value",
            "name": "무게 (%)",
            "position": "left",
            "axisLabel": {
                "fontFamily": "Noto Sans CJK KR"
            },
            "splitLine": {
                "lineStyle": {
                    "color": "#eee"
                }
            }
        },
        {
            "type": "value",
            "name": "온도 (°C)",
            "position": "right",
            "axisLabel": {
                "fontFamily": "Noto Sans CJK KR"
            },
            "splitLine": {
                "show": False
            }
        }
    ],
    "series": [
        {
            "name": "Weight (%)",
            "type": "line",
            "yAxisIndex": 0,
            "data": [[t, w] for t, w in zip(time_data, weight_data)],
            "smooth": True,
            "lineStyle": {
                "color": "#1f4e9c",
                "width": 2
            },
            "itemStyle": {
                "color": "#1f4e9c"
            },
            "markPoint": {
                "data": [
                    {
                        "coord": [time_at_140, weight_at_140],
                        "symbolSize": 8,
                        "label": {
                            "show": True,
                            "formatter": f"{weight_at_140:.1f}%",
                            "position": "top",
                            "fontSize": 12,
                            "fontFamily": "Noto Sans CJK KR"
                        }
                    }
                ]
            }
        },
        {
            "name": "Temperature (°C)",
            "type": "line",
            "yAxisIndex": 1,
            "data": [[t, temp] for t, temp in zip(time_data, temp_data)],
            "smooth": True,
            "lineStyle": {
                "color": "#c0392b",
                "width": 2
            },
            "itemStyle": {
                "color": "#c0392b"
            }
        }
    ]
}

output = {
    "figures": [
        {
            "name": "plot1",
            "option": option,
            "width": 614,
            "height": 442,
            "dpi": 300,
            "formats": ["png"]
        }
    ]
}

print(json.dumps(output, ensure_ascii=False))
